const input = $json.body ?? $json;
const allowedHosts = new Set(['files2.heygen.ai', 'resource2.heygen.ai', 'dynamic.heygen.ai']);

function requireString(value, name, max) {
  if (typeof value !== 'string' || !value.trim()) throw new Error(`${name} is required`);
  const cleaned = value.trim();
  if (cleaned.length > max) throw new Error(`${name} exceeds ${max} characters`);
  return cleaned;
}

function sourceUrl(value, name, required = true) {
  if ((value === null || value === undefined || value === '') && !required) return null;
  const raw = requireString(value, name, 4096);
  const match = raw.match(/^https:\/\/([^\/?#]+)([\/?#].*)?$/i);
  if (!match) throw new Error(`${name} must use HTTPS`);

  const authority = match[1];
  if (authority.includes('@')) throw new Error(`${name} must not contain credentials`);
  if (authority.startsWith('[')) throw new Error(`${name} host is not allowlisted`);

  const parts = authority.split(':');
  if (parts.length > 2) throw new Error(`${name} host is not allowlisted`);
  const hostname = parts[0].toLowerCase();
  if (!allowedHosts.has(hostname)) throw new Error(`${name} host is not allowlisted`);

  if (parts.length === 2) {
    if (!/^\d{1,5}$/.test(parts[1])) throw new Error(`${name} has an invalid port`);
    const port = Number(parts[1]);
    if (port < 1 || port > 65535) throw new Error(`${name} has an invalid port`);
  }

  return raw;
}

const privacy = ['private', 'unlisted', 'public'].includes(input.privacy_status) ? input.privacy_status : 'private';
const tags = Array.isArray(input.tags) ? input.tags.filter(v => typeof v === 'string' && v.trim()).slice(0, 30).map(v => v.trim().slice(0,100)) : [];
const category = typeof input.category_id === 'string' && /^\d+$/.test(input.category_id) ? input.category_id : '28';

return [{
  json: {
    request_id: typeof input.request_id === 'string' && input.request_id.trim() ? input.request_id.trim() : crypto.randomUUID(),
    video_url: sourceUrl(input.video_url, 'video_url'),
    thumbnail_url: sourceUrl(input.thumbnail_url, 'thumbnail_url', false),
    title: requireString(input.title, 'title', 100),
    description: typeof input.description === 'string' ? input.description.slice(0, 5000) : '',
    tags,
    tags_csv: tags.join(','),
    privacy_status: privacy,
    category_id: category,
    made_for_kids: input.made_for_kids === true,
    notify_subscribers: input.notify_subscribers === true
  }
}];

const upload = $('Upload Video to YouTube').first().json;
const normalized = $('Normalize + Validate').first().json;
const videoId = upload.id ?? upload.videoId ?? upload.video_id;
if (!videoId) throw new Error('YouTube upload completed without a video ID');
return [{ json: { ok: true, status: 'published', request_id: normalized.request_id, video_id: videoId, youtube_url: `https://youtu.be/${videoId}`, privacy_status: normalized.privacy_status, thumbnail_set: true } }];

